WITH prev_events AS (SELECT *, LAG(event_time) OVER (PARTITION BY event_type ORDER BY event_time, id) AS prev_event_time FROM web_events), flagged AS (SELECT *, CASE WHEN prev_event_time IS NULL OR event_time > prev_event_time + INTERVAL '90' DAY THEN 1 ELSE 0 END AS new_group_flag FROM prev_events), islands AS (SELECT id, session_id, event_type, event_time, duration_sec, SUM(new_group_flag) OVER (PARTITION BY event_type ORDER BY event_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_id_2 FROM flagged) SELECT DATE_TRUNC('WEEK', event_time) AS week_start, MAX(event_time) AS last_seen, SUM(CASE WHEN event_type = 'purchase' THEN session_id_2 ELSE 0 END) AS purchase_session_id_2, COUNT(*) FILTER (WHERE event_type = 'click') AS click_rows FROM islands GROUP BY week_start
